mapper.select:
SELECT FROM system_prompt_config WHERE 1 = 1
AND prompt_type = #{promptType}
AND enabled = #{enabled}
AND ( prompt_key LIKE CONCAT('%', #{keyword}, '%') OR prompt_name LIKE CONCAT('%', #{keyword}, '%') OR remark LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY id ASC

mapper.update:
UPDATE system_prompt_config
SET enabled = #{enabled},
    version = version + 1,
    update_by = #{updateBy},
    update_time = #{updateTime}
WHERE id = #{id}
